def transform(grid):
    """
    Task-596f2002 transformation: Map ghost 8 cells to values based on row bands.

    Row band mapping (1-indexed band):
    - Band 12-13 (rows 12-13): value = 2
    - Band 14-15 (rows 14-15): value = 1
    - Band 16-17 (rows 16-17): 
        - Cols 4-5: value = 1
        - Cols 6-9: value = 3
    - Band 18-19 (rows 18-19): value = 4
    """
    height = len(grid)
    width = len(grid[0]) if height > 0 else 0
    output = [[0] * width for _ in range(height)]

    for r in range(height):
        for c in range(width):
            if grid[r][c] == 8:
                # Determine value based on row band and column position
                if 12 <= r <= 13:
                    val = 2
                elif 14 <= r <= 15:
                    val = 1
                elif 16 <= r <= 17:
                    if 4 <= c <= 5:
                        val = 1
                    else:
                        val = 3
                elif 18 <= r <= 19:
                    val = 4
                else:
                    val = 0
                output[r][c] = val

    return output
